-- Nur Finance dataset — SQL Server. Generated by scripts/make_dataset.py (seed 20261016).
-- 1) Run the CREATE TABLE block. 2) Load each CSV from data/raw/ with the loader shown at the bottom.

CREATE TABLE branches (
  branch_id BIGINT,
  branch_name NVARCHAR(100),
  region NVARCHAR(100),
  opened_on DATE
);

CREATE TABLE products (
  product_id BIGINT,
  code NVARCHAR(100),
  name NVARCHAR(100),
  min_amount BIGINT,
  max_amount BIGINT,
  annual_rate DECIMAL(10,4),
  channel NVARCHAR(100)
);

CREATE TABLE staff (
  staff_id BIGINT,
  branch_id BIGINT,
  role NVARCHAR(100),
  full_name NVARCHAR(100),
  hired_on DATE
);

CREATE TABLE customers (
  customer_id BIGINT,
  first_name NVARCHAR(100),
  last_name NVARCHAR(100),
  sex NVARCHAR(100),
  birth_date DATE,
  region NVARCHAR(100),
  segment NVARCHAR(100),
  income_source NVARCHAR(100),
  monthly_income BIGINT,
  phone NVARCHAR(100),
  registered_at DATE
);

CREATE TABLE applications (
  application_id BIGINT,
  customer_id BIGINT,
  product_id BIGINT,
  branch_id BIGINT,
  channel NVARCHAR(100),
  applied_at DATETIME2,
  requested_amount BIGINT,
  term_months BIGINT,
  credit_score BIGINT,
  status NVARCHAR(100),
  decided_at DATE,
  officer_id BIGINT
);

CREATE TABLE loans (
  loan_id BIGINT,
  application_id BIGINT,
  customer_id BIGINT,
  product_id BIGINT,
  branch_id BIGINT,
  disbursed_at DATE,
  principal BIGINT,
  term_months BIGINT,
  annual_rate DECIMAL(10,4),
  monthly_payment BIGINT,
  risk_grade NVARCHAR(100),
  status NVARCHAR(100),
  closed_at DATE
);

CREATE TABLE installments (
  installment_id BIGINT,
  loan_id BIGINT,
  installment_no BIGINT,
  due_date DATE,
  principal_due BIGINT,
  interest_due BIGINT,
  total_due BIGINT
);

CREATE TABLE payments (
  payment_id BIGINT,
  loan_id BIGINT,
  installment_id BIGINT,
  paid_at DATE,
  amount BIGINT,
  method NVARCHAR(100)
);

CREATE TABLE collections_actions (
  action_id BIGINT,
  loan_id BIGINT,
  action_date DATE,
  action_type NVARCHAR(100),
  collector_id BIGINT,
  outcome NVARCHAR(100)
);

CREATE TABLE app_events (
  event_id BIGINT,
  customer_id BIGINT,
  event_name NVARCHAR(100),
  event_time DATETIME2,
  application_id BIGINT,
  device NVARCHAR(100),
  app_version NVARCHAR(100)
);

CREATE TABLE dim_date (
  date_key DATE,
  year BIGINT,
  quarter BIGINT,
  month BIGINT,
  month_name NVARCHAR(100),
  day BIGINT,
  weekday NVARCHAR(100),
  is_weekend BIGINT
);

